<?php include 'config.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $h=password_hash($_POST['password'],PASSWORD_DEFAULT); $stmt=$conn->prepare("INSERT INTO users(full_name,email,password,phone,address,role) VALUES(?,?,?,?,?,'customer')");$stmt->bind_param('sssss',$_POST['full_name'],$_POST['email'],$h,$_POST['phone'],$_POST['address']);$stmt->execute(); header('Location: login.php');} ?><!DOCTYPE html><html><head><meta charset="UTF-8"><title>Register</title><link rel="stylesheet" href="css/style.css"></head><body><?php include 'nav.php'; ?><form class="form" method="POST"><h1>Register</h1><input name="full_name" placeholder="Full Name"><input name="email" placeholder="Email"><input name="password" type="password" placeholder="Password"><input name="phone" placeholder="Phone"><textarea name="address" placeholder="Address"></textarea><button>Register</button></form></body></html>